def phi(n):
    result = n
    p = 2
    while p * p <= n:
        if n % p == 0:
            while n % p == 0:
                n //= p
            result -= result // p
        p += 1
    return result

def order_mod(a, n):
    if n == 1:
        return 1

    # Euler's totient function
    totient = phi(n)

    # Find divisors of totient
    divisors = []
    for i in range(1, int(totient**0.5) + 1):
        if totient % i == 0:
            divisors.append(i)
            if i*i != totient:
                divisors.append(totient // i)

    # Check smallest divisor k such that a^k = 1 (mod n)
    for k in sorted(divisors):
        if pow(a, k, n) == 1:
            return k
    return totient # Should not happen if a is coprime to n

