def order_mod(a, m):
    if math.gcd(a, m) != 1:
        return None # Should not happen

    phi_m = euler_phi(m, prime_factorization(m))

    # Find all divisors of phi_m
    divisors = []
    for i in range(1, int(math.sqrt(phi_m)) + 1):
        if phi_m % i == 0:
            divisors.append(i)
            if i * i != phi_m:
                divisors.append(phi_m // i)

    # Check the smallest divisor that satisfies 3^d === 1 mod 10000
    for d in sorted(divisors):
        if pow(a, d, m) == 1:
            return d
    return phi_m # Should return phi_m if loop fails, though it shouldn't

